32:/** The periods on a sheet: named, each running from a day to a day, none overlapping another. */
33:@Service
34:public class PeriodService {
35:
36:    private final PeriodRepository periods;
37:    private final SheetService sheets;
38:    private final ClaimRepository claims;
39:    private final PersonRepository people;
40:    private final Dues dues;
140:    }
141:
142:    /** What a rollover came to: the periods it generated, and every period it changed (those made
143:     *  and the new year's first period, whose openings it added to). */
144:    public record RolledOver(List<Period> made, List<Period> changed) {
145:    }
146:
147:    /** Roll the fiscal year named by the year over: generate the next fiscal year's twelve periods as
148:     *  {@link #generateFiscalYear} does, then add each person's open figure at the end of the old
149:     *  year's last period to their opening balance for the new year's first period. A person's open
150:     *  figure is the due of their claims that count, whose due-by falls in a period of the old year,
151:     *  and that were OPEN or PENDING at that last period's end; what an earlier rollover of the same
152:     *  year, not undone, added there is taken off it. The rollover is kept so it can be undone
153:     *  ({@link #undoRollover}). Refused unless the user acts as a steward, or when the old year has
154:     *  no periods. */
155:    @Transactional
156:    public synchronized RolledOver rollover(String sheetId, String user, int year) {
157:        sheets.load(sheetId, user);
158:        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
159:            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may roll a year over");
160:        }
161:        int fiscalStartMonth = sheets.fiscalStartMonth(sheetId);
162:        String oldFy = "FY" + year;
163:        List<Period> oldYear = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
164:                .filter(p -> fiscalYear(p.getFromDate(), fiscalStartMonth).equals(oldFy)).toList();
165:        if (oldYear.isEmpty()) {
166:            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "That fiscal year has no periods");
167:        }
168:        LocalDate end = oldYear.stream().map(Period::getToDate).max(LocalDate::compareTo).orElseThrow();
169:        List<Period> made = generateFiscalYear(sheetId, user, year + 1);
170:        String newFy = "FY" + (year + 1);
171:        Period first = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
172:                .filter(p -> fiscalYear(p.getFromDate(), fiscalStartMonth).equals(newFy)).findFirst()
173:                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
174:                        "The next fiscal year has no first period"));
175:        List<Person> onSheet = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
176:        Map<Long, BigDecimal> open = new HashMap<>();
177:        LocalDate today = sheets.today(sheetId);
178:        for (Claim c : claims.findBySheetIdOrderByListedDesc(sheetId)) {
179:            Person person = onSheet.stream().filter(p -> p.getId().equals(c.getPersonId())).findFirst().orElse(null);
180:            boolean inOldYear = oldYear.stream().anyMatch(p -> !c.getDueBy().isBefore(p.getFromDate())
181:                    && !c.getDueBy().isAfter(p.getToDate()));
182:            if (person == null || !inOldYear || !Dues.countsAsOf(person, c, end, today)) {
183:                continue;
184:            }
185:            ClaimStatus then = c.statusOn(end);
186:            if (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING) {
187:                continue;
188:            }
189:            BigDecimal figure = dues.figure(sheetId, person, c);
190:            if (figure != null) {
191:                open.merge(person.getId(), figure, BigDecimal::add);
192:            }
193:        }
194:        Period locked = periods.lockByIdAndSheetId(first.getId(), sheetId)
195:                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
196:        // what an earlier rollover of the year, not undone, already set there is not set again
197:        Map<Long, BigDecimal> already = new HashMap<>();
198:        for (Rollover earlier : rollovers.findBySheetIdAndFyAndUndoneFalse(sheetId, oldFy)) {
199:            if (earlier.getOpeningPeriodId().equals(locked.getId())) {
200:                earlier.getOpenings().forEach((personId, amount) -> already.merge(personId, amount, BigDecimal::add));
201:            }
202:        }
203:        Map<Long, BigDecimal> openings = new HashMap<>();
204:        for (Person person : onSheet) {
205:            BigDecimal amount = open.getOrDefault(person.getId(), BigDecimal.ZERO)
206:                    .subtract(already.getOrDefault(person.getId(), BigDecimal.ZERO));
207:            if (amount.signum() == 0) {
208:                continue;
209:            }
210:            amount = amount.setScale(2);
211:            locked.addOpening(person.getId(), amount);
212:            openings.put(person.getId(), amount);
213:            audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + user + " name=" + person.getName()
214:                    + " period=" + locked.getName() + " amount=" + amount.toPlainString());
215:        }
216:        Period saved = periods.saveAndFlush(locked);
217:        rollovers.save(new Rollover(sheetId, user, today, oldFy, saved.getId(),
218:                made.stream().map(Period::getId).collect(Collectors.toSet()), openings));
219:        audit.recordOnCommit("ROLLOVER sheet=" + sheetId + " by=" + user + " fy=" + oldFy + " periods=" + made.size());
220:        history.record(sheetId);
221:        List<Period> changed = new ArrayList<>(made.stream().filter(p -> !p.getId().equals(saved.getId())).toList());
222:        changed.add(saved);
223:        return new RolledOver(made, changed);
224:    }
