231:    /** Undo the last rollover made on the sheet: remove the periods it generated and take back the
232:     *  opening balances it set. Refused unless the user is a steward and the one who made it, on the
233:     *  sheet-today it was made, it is not already undone, and no claim on the sheet now belongs to
234:     *  (is due by a day inside) a period it generated. */
235:    @Transactional
236:    public synchronized RolloverUndone undoRollover(String sheetId, String user) {
237:        sheets.load(sheetId, user);
238:        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
239:            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may undo a rollover");
240:        }
241:        Rollover last = rollovers.findFirstBySheetIdOrderByIdDesc(sheetId)
242:                .filter(r -> !r.isUndone())
243:                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "There is no rollover to undo"));
244:        if (!last.getMadeBy().equals(user)) {
245:            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only the steward who made the rollover may undo it");
246:        }
247:        if (!last.getMadeOn().equals(sheets.today(sheetId))) {
248:            throw new ResponseStatusException(HttpStatus.CONFLICT, "A rollover can only be undone on the day it was made");
249:        }
250:        List<Period> generated = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
251:                .filter(p -> last.getPeriodIds().contains(p.getId())).toList();
